import {requireVendor} from '@/lib/auth/vendor';
export default async function VendorSettingsPage(){const context=await requireVendor();return <><div className="vendor-page-head"><div><p className="section-kicker">Préférences</p><h1>Paramètres</h1><p>Les réglages utiles, sans complexité.</p></div></div><section className="vendor-card settings-minimal"><h2>Votre accès</h2><dl><div><dt>Restaurant</dt><dd>{context.restaurant!.name}</dd></div><div><dt>Votre rôle</dt><dd>{context.restaurant!.role==='owner'?'Propriétaire':context.restaurant!.role==='manager'?'Responsable':'Équipe commandes'}</dd></div></dl><p>Les notifications personnalisées seront ajoutées lorsque les canaux email et WhatsApp seront activés.</p></section></>}
